import { useEffect, useMemo, useState } from 'react';
import L from 'leaflet';
import 'leaflet/dist/leaflet.css';
import { Activity, CircleAlert, RefreshCw, TrendingUp } from 'lucide-react';
import { api } from '../lib/api';
import { usePanelData } from '../hooks/usePanelData';
import {
  isStopStarred,
  starStop,
  unstarStop,
} from '../lib/favourites';
import BasemapPicker from './BasemapPicker';
import { EmptyState } from './EmptyState';
import { useLeafletPanelMap } from '../lib/useLeafletPanelMap';
import type {
  ReliabilityNode,
  ReliabilityResponse
} from '../types';
import { fmtMin, fmtPct } from '../lib/format';
import { PanelSkeleton } from './PanelStates';
import SourceNote from './SourceNote';
import NewHereHint from './NewHereHint';
import { useDataVintages } from '../lib/useDataVintages';
import DataVintageBadge from './DataVintageBadge';

/**
 * Measured transfer reliability map (Stream B).
 *
 * Every transfer stop colored by the *realized* wait riders actually face
 * under the collector's observed lateness (median + p90) and by the
 * probability that a scheduled connection fails. Read-only — nothing here is
 * optimized or proposed; this is the measured counterpart to the optimizer's
 * modeled transfer view.
 */

const LOW_DATA_COLOR = '#94a3b8'; // gray: not enough measured coverage to trust

/** Service-day pools the API can serve (validated server-side, same triple). */
const SERVICE_DAYS = [
  { value: 'weekday', label: 'Weekday' },
  { value: 'saturday', label: 'Saturday' },
  { value: 'sunday', label: 'Sunday' },
] as const;

type ServiceDay = (typeof SERVICE_DAYS)[number]['value'];

/** Color by realized median wait (minutes). Green = short, red = painful. */
function waitColor(min: number): string {
  if (min <= 6) return '#16a34a';
  if (min <= 10) return '#facc15';
  if (min <= 14) return '#f97316';
  return '#dc2626';
}

const LEGEND = [
  { label: '≤ 6 min', color: '#16a34a' },
  { label: '≤ 10', color: '#facc15' },
  { label: '≤ 14', color: '#f97316' },
  { label: '> 14', color: '#dc2626' },
  { label: 'low data', color: LOW_DATA_COLOR },
];

function nodeColor(n: ReliabilityNode): string {
  if (n.measured_share < 0.3 || n.realized_median_min == null) return LOW_DATA_COLOR;
  return waitColor(n.realized_median_min);
}

/** Radius grows with P(miss) so a likely-failing stop is unmistakable. */
function nodeRadius(n: ReliabilityNode): number {
  return 6 + Math.min(14, n.p_miss * 12);
}

export default function ReliabilityPanel() {
  const [selected, setSelected] = useState<ReliabilityNode | null>(null);
  const [serviceDay, setServiceDay] = useState<ServiceDay>('weekday');
  // 3.2 foundations (A7 follow-up): riders star stops where they already
  // are. A version counter re-renders the popups (star state is read inside
  // the bindPopup template, which Leaflet only refreshes on setPopupContent).
  const [favTick, setFavTick] = useState(0);
  const vintages = useDataVintages();
  // Shared panel-map bootstrap: deferred-mount creation, ResizeObserver,
  // basemap sync, and the mapReady-keyed tile effect. The mapReady key here
  // is the fix for the gray-forever bug: the tile effect's one [basemap] run
  // used to find leafletRef still null on a cold mount (map deferred until
  // data loads) and never re-ran.
  const {
    ref: mapRefCb,
    mapRef: leafletRef,
    layerRef,
  } = useLeafletPanelMap();

  // P2: fetch/loading/error owned by the hook, keyed on serviceDay (was a
  // useMemo'd load callback + effect pair).
  const { data, error, loading, reload } = usePanelData<ReliabilityResponse>({
    fetcher: () => api.measuredReliability(serviceDay),
    deps: [serviceDay],
  });

  useEffect(() => {
    const map = leafletRef.current;
    const layer = layerRef.current;
    if (!map || !layer || !data) return;

    layer.clearLayers();
    const pts: L.LatLng[] = [];
    for (const n of data.nodes) {
      const pt = L.latLng(n.lat, n.lon);
      pts.push(pt);
      const low = nodeColor(n) === LOW_DATA_COLOR;
      const marker = L.circleMarker(pt, {
        radius: nodeRadius(n),
        color: '#ffffff',
        weight: 1,
        fillColor: nodeColor(n),
        fillOpacity: n.stop_id === selected?.stop_id ? 0.95 : 0.7,
      });
      const missLine =
        n.p_miss > 0
          ? `<b>${fmtPct(n.p_miss * 100)}</b> miss this connection`
          : 'no observed misses';
      // Star toggle rides in the popup (favTick in deps rebinds it after a
      // toggle so the label flips without reopening). XSS-safe: stop names
      // come from our own GTFS feed; text interpolation only.
      const starred = isStopStarred(n.stop_id);
      marker.bindPopup(
        `<b>${n.stop_name}</b><br/>Routes ${n.routes.join(', ')}<br/>` +
          `realized median <b>${fmtMin(n.realized_median_min)}</b>` +
          ` · p90 <b>${fmtMin(n.realized_p90_min)}</b><br/>` +
          `scheduled median ${fmtMin(n.scheduled_median_min)}<br/>` +
          `${missLine}` +
          (low ? `<br/><i>low lateness coverage — reads as scheduled</i>` : '') +
          `<br/><button type="button" data-fav-stop="${n.stop_id}" data-fav-name="${n.stop_name.replace(/"/g, '&quot;')}" data-fav-routes="${n.routes.join(',')}" style="margin-top:6px;cursor:pointer;background:none;border:none;padding:0;color:#4cc38a;font:inherit;font-size:12px;">${starred ? '★ Saved to home — click to remove' : '☆ Save this stop to your home'}</button>`
      );
      marker.on('click', () => setSelected(n));
      layer.addLayer(marker);
    }
    if (pts.length) map.fitBounds(L.latLngBounds(pts).pad(0.15));

    // Popup star toggles: one delegated listener per layer build (the layer
    // is cleared each rebuild, so no listener leak). The handler reads the
    // stop identity off data attributes and writes through the favourites
    // store, then notifies the rider home.
    const container = typeof map.getContainer === 'function' ? map.getContainer() : null;
    if (!container) return; // test double without a real map container
    const onFavClick = (e: MouseEvent) => {
      const el = (e.target as HTMLElement).closest('[data-fav-stop]') as HTMLElement | null;
      if (!el) return;
      const stopId = el.dataset.favStop!;
      if (isStopStarred(stopId)) {
        unstarStop(stopId);
      } else {
        starStop({
          stopId,
          stopName: el.dataset.favName ?? stopId,
          routes: (el.dataset.favRoutes ?? '').split(',').filter(Boolean),
        });
      }
      window.dispatchEvent(new Event('miway:favourites-changed'));
      setFavTick((t) => t + 1); // rebind popups with the flipped label
    };
    container.addEventListener('click', onFavClick);
    return () => {
      container.removeEventListener('click', onFavClick);
    };
  }, [data, selected, leafletRef, layerRef, favTick]);

  // Worst realized waits, ranked by p90 among adequately-measured stops.
  const worst = useMemo(() => {
    if (!data) return [];
    const measured = data.nodes.filter(
      (n) =>
        n.measured_share >= 0.3 &&
        n.realized_p90_min != null &&
        // min-n gate: a p90 from fewer than 20 measured connections is noise
        n.n_connections >= 20
    );
    return [...measured]
      .sort((a, b) => (b.realized_p90_min ?? 0) - (a.realized_p90_min ?? 0))
      .slice(0, 12);
  }, [data]);

  if (loading && !data) return <PanelSkeleton label="Loading transfer reliability…" />;

  if (error) {
    return (
      <div
        role="alert"
        className="rounded-xl border border-danger/40 bg-danger/10 p-6 text-sm text-danger"
      >
        Could not load transfer reliability: {error}
      </div>
    );
  }
  if (!data || !data.available) {
    return (
      <EmptyState
        reason="Transfer reliability is not measured for this service day yet."
        onRetry={reload}
      />
    );
  }

  return (
    <div className="flex flex-col gap-3 overflow-hidden">
      <div className="relative overflow-hidden rounded-xl border border-border bg-card px-4 py-3">
        <div className="absolute inset-x-0 top-0 h-0.5 bg-border" />
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2.5">
            <span className="rounded-lg bg-optimized/15 p-1.5">
              <Activity className="h-4 w-4 text-optimized" />
            </span>
            <div>
              <h2 className="text-sm font-bold text-text-primary">
                Realized transfer waits (measured)
              </h2>
              <p className="mt-0.5 text-xs text-text-muted">
                {data.basis} · {data.n_nodes.toLocaleString()} transfer stops ·{' '}
                {data.n_connections.toLocaleString()} connections
                {data.pool_observations > 0 &&
                  ` · ${data.pool_observations.toLocaleString()} obs / ${data.pool_routes} routes`}
              </p>
              <DataVintageBadge
                vintage={vintages.lateness}
                label="lateness pool"
                className="mt-1"
              />
            </div>
          </div>
          <button
            onClick={reload}
            className="flex items-center gap-1.5 rounded-lg border border-border px-2.5 py-1.5 text-xs font-semibold text-text-secondary transition-colors hover:bg-card-hover"
          >
            <RefreshCw className="h-3.5 w-3.5" /> Reload
          </button>
        </div>
        <div className="mt-2.5 flex flex-wrap items-center gap-2">
          <span className="text-[10px] font-semibold text-text-muted">
            Service day
          </span>
          <div
            className="flex overflow-hidden rounded-lg border border-border"
            role="group"
            aria-label="Service day type"
          >
            {SERVICE_DAYS.map((d) => (
              <button
                key={d.value}
                onClick={() => setServiceDay(d.value)}
                aria-pressed={serviceDay === d.value}
                className={`px-3 py-1 text-xs font-semibold transition-colors ${ serviceDay === d.value ? 'bg-optimized text-white' : 'bg-transparent text-text-secondary hover:bg-card-hover' }`}
              >
                {d.label}
              </button>
            ))}
          </div>
          {loading && (
            <span className="text-[10px] text-text-muted" role="status">
              Loading {serviceDay} pool…
            </span>
          )}
        </div>
      </div>

      <NewHereHint text="This map is the measured half of the transfer story: it colors every stop by the wait riders actually experience under real lateness, and by how often a scheduled connection fails. The modeled 'what would improve' view lives in Fix transfers." />

      {!data.has_lateness && (
        <div className="flex items-center gap-2 rounded-xl border border-bottleneck/40 bg-bottleneck/10 px-4 py-2.5 text-xs text-bottleneck">
          <CircleAlert className="h-4 w-4" />
          No observed lateness yet — every stop renders at its scheduled wait until the
          collector records departures.
        </div>
      )}

      {/* map */}
      <div className="relative overflow-hidden rounded-xl border border-border bg-card">
        <div className="flex flex-wrap items-center gap-2.5 border-b border-border px-4 py-2.5">
          <span className="text-[10px] font-semibold text-text-muted">
            Realized wait (min) · radius = P(fail)
          </span>
          <div className="ml-auto flex items-center gap-3">
            {LEGEND.map((l) => (
              <span key={l.label} className="flex items-center gap-1 text-[10px] text-text-muted">
                <span
                  className="inline-block h-2.5 w-2.5 rounded-full"
                  style={{ background: l.color }}
                />
                {l.label}
              </span>
            ))}
          </div>
        </div>
        <div className="relative">
          <div ref={mapRefCb} className="h-[420px] w-full" style={{ background: '#e7e9eb' }} />
          <BasemapPicker className="absolute right-2 top-2" />
        </div>
      </div>

      {/* worst-realized ranking */}
      <div className="relative overflow-hidden rounded-xl border border-border bg-card">
        <div className="flex items-center gap-2.5 px-4 pt-4 pb-2">
          <span className="rounded-lg bg-danger/15 p-1.5">
            <TrendingUp className="h-4 w-4 text-danger" />
          </span>
          <h3 className="text-sm font-bold text-text-primary">
            Worst realized waits (p90 of measured)
          </h3>
        </div>
        <div className="px-4 pb-4">
          <table className="data-table w-full text-left text-xs">
            <thead>
              <tr className="border-b border-border text-[10px] text-text-muted">
                <th className="py-1.5 pr-3 font-semibold">Transfer stop</th>
                <th className="py-1.5 pr-3 font-semibold">Routes</th>
                <th className="py-1.5 pr-3 font-semibold">Realized med</th>
                <th className="py-1.5 pr-3 font-semibold">Realized p90</th>
                <th className="py-1.5 text-right font-semibold">P(miss)</th>
              </tr>
            </thead>
            <tbody>
              {worst.map((n) => (
                <tr
                  key={n.stop_id}
                  className={`cursor-pointer border-b border-border/60 ${ selected?.stop_id === n.stop_id ? 'bg-accent/10' : 'hover:bg-card-hover' }`}
                  onClick={() => setSelected(n)}
                >
                  <td className="py-1.5 pr-3 font-semibold text-text-primary">{n.stop_name}</td>
                  <td className="py-1.5 pr-3 text-text-secondary">{n.routes.join(', ')}</td>
                  <td
                    className={`py-1.5 pr-3 tabular-nums font-bold ${ n.realized_median_min != null && n.realized_median_min > 10 ? 'text-bottleneck' : 'text-text-secondary' }`}
                  >
                    {fmtMin(n.realized_median_min)}
                  </td>
                  <td className="py-1.5 pr-3 tabular-nums text-danger">
                    {fmtMin(n.realized_p90_min)}
                  </td>
                  <td className="py-1.5 text-right tabular-nums text-text-secondary">
                    {fmtPct(n.p_miss * 100)}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
        <div className="flex items-center justify-between gap-3 border-t border-border bg-bg/40 px-4 py-2.5">
          <span className="text-[10px] text-text-muted">
            Realized = scheduled wait under observed lateness. P(miss) is the share of
            connections that fail. Gray stops lack ≥30% measured coverage and read as
            scheduled.
          </span>
          <SourceNote source="GET /api/measured/reliability" />
        </div>
      </div>

    </div>
  );
}